from itertools import combinations
n=7
edges=[]
idx={}
k=0
for i in range(n):
    for j in range(i+1,n):
        edges.append((i,j)); idx[(i,j)]=k; k+=1
print(edges)
fixed={7:1,8:0,13:0,14:1}
# brute force all remaining
vars=[i for i in range(21) if i not in fixed]
tri_edges=[]
for tri in combinations(range(n),3):
    tri_edges.append([idx[tuple(sorted(e))] for e in combinations(tri,2)])
blue4=[]
for S in combinations(range(n),4):
    blue4.append([idx[tuple(sorted(e))] for e in combinations(S,2)])

def ok(assign):
    # no red triangle: not all 0
    for es in tri_edges:
        if all(assign[e]==0 for e in es): return False
    for es in blue4:
        if all(assign[e]==1 for e in es): return False
    return True
count=0
solutions=[]
for mask in range(1<<len(vars)):
    a=[None]*21
    for i,v in fixed.items(): a[i]=v
    for t,e in enumerate(vars):
        a[e]=(mask>>t)&1
    if ok(a):
        count+=1
        solutions.append(a)
        print('sol', a)
        break
print('count first?', count)
